-- V45: 식재료 대표 이미지(image_url) 백필.
-- 위키백과(CC/PD) 대표사진을 수집·리사이즈하여 S3(ingredients/{id}.jpg)에 적재, CloudFront URL로 저장.
-- IngredientService는 image_url을 MediaUrlResolver로 감싸지 않고 raw 반환하므로 전체 URL을 저장한다
-- (절대 URL은 추후 resolve()로 감싸도 그대로 통과하여 안전). 매칭은 이름 기준(환경독립), image_url IS NULL 가드로 멱등.

UPDATE ingredients SET image_url='https://d1lcjrcsx3pn64.cloudfront.net/ingredients/1.jpg' WHERE name='쌀' AND active=true AND image_url IS NULL;
